importScripts('/vendor/xlsx/xlsx.full.min.js');
self.onmessage=function(event){try{const book=XLSX.utils.book_new();book.Workbook={Views:[{RTL:true}]};const report=XLSX.utils.aoa_to_sheet([['تقرير ميزان'],...event.data.lines.map(line=>[line])]);report['!cols']=[{wch:110}];XLSX.utils.book_append_sheet(book,report,'التقرير');const facts=XLSX.utils.json_to_sheet(event.data.facts||[]);XLSX.utils.book_append_sheet(book,facts,'البيانات المالية');const buffer=XLSX.write(book,{bookType:'xlsx',type:'array'});self.postMessage({buffer},[buffer]);}catch(e){self.postMessage({error:'تعذر إنشاء ملف Excel: '+e.message})}};
